import bcrypt from'bcryptjs';import{query}from'./db.js';const demo=[['Victor Oliveira','admin@cactusponto.local','ADMIN','22222222-2222-4222-8222-222222222221'],['Renata Alves','rh@cactusponto.local','HR','22222222-2222-4222-8222-222222222224'],['Marina Costa','gestor@cactusponto.local','MANAGER','22222222-2222-4222-8222-222222222222'],['Lucas Martins','colaborador@cactusponto.local','EMPLOYEE','22222222-2222-4222-8222-222222222223']];export async function bootstrap(){const tenant='11111111-1111-4111-8111-111111111111',exists=await query(`SELECT 1 FROM tenants WHERE id=$1`,[tenant]);if(!exists.rowCount)return;const hash=await bcrypt.hash('Cactus@123',12);for(const[name,email,role,employee]of demo)await query(`INSERT INTO users(tenant_id,employee_id,name,email,password_hash,role) SELECT $1,$2,$3,$4,$5,$6 WHERE EXISTS(SELECT 1 FROM employees WHERE tenant_id=$1 AND id=$2) ON CONFLICT(tenant_id,email) DO NOTHING`,[tenant,employee,name,email,hash,role])}